package com.vandorlabs.neoforge.reservoir.client;
import com.vandorlabs.neoforge.*;import com.vandorlabs.neoforge.reservoir.*;import com.vandorlabs.neoforge.client.NativeMaterialPicker;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.neoforged.neoforge.network.PacketDistributor;
/** Same material list, shape choices, status gauge and previous-value cycling as Source storage. */
public final class NativeBufferScreen extends AbstractContainerScreen<NativeBufferMenu> {
 private int casing,layout;private boolean block;private NativeMaterialPicker picker;private Button shapeButton,layoutButton;private int controls;private int fluidColor=0xff3388dd;private String fluidLabel="Empty";
 public NativeBufferScreen(NativeBufferMenu menu,Inventory inventory,Component title){super(menu,inventory,title);casing=menu.tile.casing();layout=menu.tile instanceof NativeBatteryEntity?1:menu.tile.settings().layout;block=menu.tile.blockShape();}
 public NativeMaterialPicker picker(){return picker;}
 @Override protected void containerTick(){super.containerTick();if(menu.tile instanceof NativeHexTankEntity tank){net.neoforged.neoforge.fluids.FluidStack first=net.neoforged.neoforge.fluids.FluidStack.EMPTY;boolean mixed=false;for(var cell:tank.members()){var value=cell.visibleFluid();if(!value.isEmpty()){if(first.isEmpty())first=value;else if(!net.neoforged.neoforge.fluids.FluidStack.isSameFluidSameComponents(first,value))mixed=true;}}fluidLabel=first.isEmpty()?"Empty":mixed?"Mixed fluids":first.getHoverName().getString();if(!first.isEmpty())fluidColor=0xff000000|net.neoforged.neoforge.client.extensions.common.IClientFluidTypeExtensions.of(first.getFluid()).getTintColor(first);}}

 @Override protected void init(){imageWidth=Math.min(354,width-16);imageHeight=Math.min(238,height-16);super.init();controls=imageWidth/2+14;clearWidgets();picker=new NativeMaterialPicker(casing,id->ModernFinishCatalog.option(id).general(),choice->{casing=choice;send();});if(menu.tile instanceof NativeBatteryEntity)picker.originalArtwork("vandorlabs:blocks/matter/casing");picker.layout(leftPos+12,topPos+38,imageWidth/2-22,(imageHeight-62)/22,false);addRenderableWidget(picker.searchField());shapeButton=com.vandorlabs.neoforge.client.NativeDialogButton.builder(shapeLabel(),button->{block=!block;send();labels();}).bounds(leftPos+controls,topPos+imageHeight-(menu.tile instanceof NativeBatteryEntity?66:94),imageWidth-controls-12,20).build();addRenderableWidget(shapeButton);if(!(menu.tile instanceof NativeBatteryEntity)){layoutButton=com.vandorlabs.neoforge.client.NativeDialogButton.builder(layoutLabel(),button->{layout=layout==1?2:1;send();labels();}).bounds(leftPos+controls,topPos+imageHeight-66,imageWidth-controls-12,20).build();addRenderableWidget(layoutButton);}addRenderableWidget(com.vandorlabs.neoforge.client.NativeDialogButton.builder(Component.translatable("gui.done"),button->onClose()).bounds(leftPos+controls,topPos+imageHeight-32,imageWidth-controls-12,20).build());}
 private Component shapeLabel(){return Component.literal("Shape: "+(block?"Block":"Hexagon"));}private Component layoutLabel(){return Component.literal("Texture: "+(layout==1?"Tile":"Fit (Aspect)"));}private void labels(){shapeButton.setMessage(shapeLabel());if(layoutButton!=null)layoutButton.setMessage(layoutLabel());}
 private void send(){PacketDistributor.sendToServer(new NativeBufferSettingsPayload(menu.containerId,menu.tile.getBlockPos(),casing,layout,block));}
 @Override public boolean mouseClicked(double x,double y,int button){if(button==1){if(shapeButton.isMouseOver(x,y)){block=!block;send();labels();return true;}if(layoutButton!=null&&layoutButton.isMouseOver(x,y)){layout=layout==1?2:1;send();labels();return true;}}return picker.click(x,y,button)||super.mouseClicked(x,y,button);}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){return picker.drag(x,y)||super.mouseDragged(x,y,button,dx,dy);}@Override public boolean mouseReleased(double x,double y,int button){picker.release();return super.mouseReleased(x,y,button);}@Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){return picker.wheel(x,y,vertical)||super.mouseScrolled(x,y,horizontal,vertical);}@Override public boolean keyPressed(int key,int scan,int modifiers){if(key==org.lwjgl.glfw.GLFW.GLFW_KEY_ESCAPE&&picker.inventoryPicker()!=null){picker.closeInventory();return true;}return picker.keyPressed(key,scan,modifiers)||super.keyPressed(key,scan,modifiers);}
 @Override public void renderBackground(GuiGraphics g,int x,int y,float partial){g.fillGradient(0,0,width,height,0xC0101010,0xD0101010);renderBg(g,partial,x,y);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){com.vandorlabs.neoforge.client.NativeDialogVisuals.panel(g,font,title,leftPos,topPos,imageWidth,imageHeight,com.vandorlabs.ui.DialogStyle.BUFFER);g.drawString(font,"Casing",leftPos+12,topPos+26,0x96a8ba,false);picker.render(g,x,y);int gx=leftPos+controls,gy=topPos+38,h=88;g.fill(gx-2,gy-2,gx+20,gy+h+2,0xff98a8b8);g.fill(gx,gy,gx+18,gy+h,0xff0c1219);int capacity=menu.capacity(),amount=menu.amount(),filled=capacity<=0?0:(int)Math.round(h*(double)amount/capacity);g.fill(gx,gy+h-filled,gx+18,gy+h,menu.tile instanceof NativeBatteryEntity?0xff62d884:fluidColor);int tx=gx+28,w=imageWidth-controls-40;String units=menu.tile instanceof NativeBatteryEntity?" RF":" mB";g.drawWordWrap(font,Component.literal(amount+" / "+capacity+units),tx,topPos+42,w,0xffffff);g.drawString(font,String.format(java.util.Locale.ROOT,"%.1f%% full",capacity<=0?0:100D*amount/capacity),tx,topPos+76,0xcdd7e4,false);g.drawWordWrap(font,Component.literal(menu.tile instanceof NativeBatteryEntity?"Green port: RF input\nOrange port: RF output":amount==0?"Empty":fluidLabel),tx,topPos+98,w,0xcdd7e4);}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){}@Override public boolean isPauseScreen(){return false;}
}
